create table if not exists public.quote_requests(id uuid primary key default gen_random_uuid(),reference text unique not null,user_id uuid references public.profiles(id),first_name text not null,last_name text not null,phone text not null,email text,department text not null,municipality text not null,items jsonb not null check(jsonb_typeof(items)='array' and jsonb_array_length(items)>0),notes text,status text not null default 'pending' check(status in('pending','reviewing','quoted','approved','rejected','purchased','completed','cancelled')),product_cost numeric(12,2),shipping_cost numeric(12,2),service_fee numeric(12,2),total numeric(12,2),admin_notes text,quoted_by uuid references public.profiles(id),quoted_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists quote_requests_reference_idx on public.quote_requests(reference);create index if not exists quote_requests_status_idx on public.quote_requests(status,created_at desc);create index if not exists quote_requests_phone_idx on public.quote_requests(phone);
create trigger quote_requests_touch before update on public.quote_requests for each row execute function public.touch_updated_at();alter table public.quote_requests enable row level security;
create policy "customers view own quotes" on public.quote_requests for select using(user_id=auth.uid() or public.has_role('admin') or public.has_role('supervisor'));
create policy "staff manage quotes" on public.quote_requests for all using(public.has_role('admin') or public.has_role('supervisor')) with check(public.has_role('admin') or public.has_role('supervisor'));
